<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import type {EChartsOption} from 'echarts'
import {scenariosApi,type ScenarioVersionCreate} from '@/api/scenarios';import {simulationApi} from '@/api/simulation';import {recommendationsApi} from '@/api/recommendations';import {useSiteStore} from '@/stores/site'
import PageHeader from '@/components/PageHeader.vue';import BaseChart from '@/components/BaseChart.vue';import LoadingState from '@/components/LoadingState.vue';import EmptyState from '@/components/EmptyState.vue';import ErrorState from '@/components/ErrorState.vue';import StatusTag from '@/components/StatusTag.vue'
import type {RecommendationPath,RecommendationRun,Scenario,ScenarioComparisonResult,ScenarioVersion,SimulationBatch} from '@/types'

interface BaselineExperimentContext{locked?:boolean;dataset_provenance?:{dataset_id?:string};time_range?:{start_utc?:string;end_utc_exclusive?:string;completeness_rate?:number};baseline_metrics?:Record<string,number|string>;model_versions?:{hourly_simulation?:string};accounting_simulation_bridge?:{status?:string;difference_kwh?:number}}

const route=useRoute(),router=useRouter(),siteStore=useSiteStore();const loading=ref(true),busy=ref(false),error=ref<string|null>(null),operationError=ref<string|null>(null)
const scenarios=ref<Scenario[]>([]),versionMap=reactive<Record<number,ScenarioVersion[]>>({}),selectedScenarioId=ref<number|null>(null),selectedVersionId=ref<number|null>(null),recommendationRuns=ref<RecommendationRun[]>([])
const batches=ref<SimulationBatch[]>([]),selectedBatchId=ref<number|null>(null),batch=ref<SimulationBatch|null>(null),selectedVersionIds=ref<number[]>([]),baselineVersionId=ref<number|null>(null),batchYear=ref(new Date().getFullYear()),buyPrice=ref(.57),sellPrice=ref(.42)
const createVisible=ref(false),snapshotText=ref(''),snapshotError=ref<string|null>(null),comparisonMetric=ref('cumulative_carbon_emission_t')
const typeLabels:Record<string,string>={BASELINE:'基准场景',ECONOMIC:'经济优先',REDUCTION:'减排优先',BALANCED:'综合平衡',CUSTOM:'自定义'}
const metricLabels:Record<string,string>={cumulative_carbon_emission_t:'累计碳排',cumulative_carbon_reduction_t:'累计减排',reduction_rate:'减排率',total_grid_power_kwh:'总购电量',renewable_generation_kwh:'可再生能源发电量',renewable_self_consumption_rate:'可再生能源自用率',storage_charge_kwh:'储能充电量',storage_discharge_kwh:'储能放电量',total_electricity_cost:'总电费',investment:'投资额',payback_years:'回收期',target_satisfaction:'目标满足度',max_energy_balance_error_kwh:'最大能源守恒误差'}
const currentScenario=computed(()=>scenarios.value.find(x=>x.id===selectedScenarioId.value)||null),versions=computed(()=>selectedScenarioId.value?versionMap[selectedScenarioId.value]||[]:[]),selectedVersion=computed(()=>versions.value.find(x=>x.id===selectedVersionId.value)||null)
const baselineContext=computed(()=>selectedVersion.value?.parameter_snapshot_json.experiment_context as BaselineExperimentContext|undefined)
const baselineMetric=(key:string)=>baselineContext.value?.baseline_metrics?.[key]
const baselineNumber=(key:string,unit:string)=>{const raw=baselineMetric(key);return typeof raw==='number'?`${raw.toLocaleString('zh-CN',{maximumFractionDigits:6})} ${unit}`:String(raw??'NOT_VERIFIED')}
const currentVersion=(scenario:Scenario)=>versionMap[scenario.id]?.find(x=>x.id===scenario.current_version_id)||versionMap[scenario.id]?.at(-1)||null
const comparisonItems=computed(()=>batch.value?.comparison_json?.items||[]),batchMetrics=computed(()=>batch.value?.comparison_json?.metrics||Object.keys(metricLabels))
const successful=computed(()=>batch.value?.items.filter(x=>x.status==='SUCCESS').length||0),failed=computed(()=>batch.value?.items.filter(x=>x.status==='FAILED').length||0)
const recommendationIndex=computed(()=>{const map=new Map<number,{run:RecommendationRun;path:RecommendationPath}>();for(const run of recommendationRuns.value)for(const path of run.recommendations)map.set(path.id,{run,path});return map})
const source=(version:ScenarioVersion|null)=>version?.source_recommendation_id?recommendationIndex.value.get(version.source_recommendation_id):undefined
const scenarioName=(versionId:number)=>{const scenario=scenarios.value.find(s=>versionMap[s.id]?.some(v=>v.id===versionId));return scenario?.name||`Version #${versionId}`}
const versionType=(versionId:number)=>Object.values(versionMap).flat().find(x=>x.id===versionId)?.scenario_type||'CUSTOM'
const value=(v:number|null|undefined)=>v===null||v===undefined?'暂无数据':v.toLocaleString('zh-CN',{maximumFractionDigits:6})
const percentMetric=(key:string)=>['reduction_rate','renewable_self_consumption_rate','target_satisfaction'].includes(key)
const displayMetric=(key:string,v:number|null|undefined)=>v===null||v===undefined?'暂无数据':percentMetric(key)?`${(v*100).toFixed(2)}%`:value(v)
const latestTime=(scenario:Scenario)=>currentVersion(scenario)?.created_at||scenario.created_at
const measureSummary=(version:ScenarioVersion|null)=>version?.parameter_snapshot_json.measures?.map(x=>x.measure_type).join('、')||'无低碳措施'
const chartOption=(key:string):EChartsOption=>({grid:{left:75,right:20,top:42,bottom:70},xAxis:{type:'category',axisLabel:{rotate:20},data:comparisonItems.value.map(x=>scenarioName(x.scenario_version_id))},yAxis:{type:'value'},series:[{name:metricLabels[key],type:'bar',data:comparisonItems.value.map(x=>x[key as keyof ScenarioComparisonResult] as number|null),itemStyle:{color:'#397d69'}}]})
const carbonOption=computed(()=>chartOption('cumulative_carbon_emission_t')),reductionOption=computed(()=>chartOption('cumulative_carbon_reduction_t')),gridOption=computed(()=>chartOption('total_grid_power_kwh')),renewableOption=computed(()=>chartOption('renewable_generation_kwh')),selfUseOption=computed(()=>chartOption('renewable_self_consumption_rate')),costOption=computed(()=>chartOption('total_electricity_cost'))
const investmentPaybackOption=computed<EChartsOption>(()=>({grid:{left:65,right:65,top:45,bottom:70},xAxis:{type:'category',axisLabel:{rotate:20},data:comparisonItems.value.map(x=>scenarioName(x.scenario_version_id))},yAxis:[{type:'value',name:'投资额'},{type:'value',name:'回收期 年'}],series:[{name:'投资额',type:'bar',data:comparisonItems.value.map(x=>x.investment)},{name:'回收期',type:'line',yAxisIndex:1,data:comparisonItems.value.map(x=>x.payback_years)}]}))
const deltaOption=computed<EChartsOption>(()=>({grid:{left:70,right:70,top:48,bottom:75},xAxis:{type:'category',axisLabel:{rotate:20},data:comparisonItems.value.map(x=>scenarioName(x.scenario_version_id))},yAxis:[{type:'value',name:'绝对差值'},{type:'value',name:'变化率'}],series:[{name:'绝对差值',type:'bar',data:comparisonItems.value.map(x=>x.baseline_delta?.[comparisonMetric.value]??null)},{name:'变化率',type:'line',yAxisIndex:1,data:comparisonItems.value.map(x=>x.baseline_change_rate?.[comparisonMetric.value]??null)}]}))
const scatterOption=computed<EChartsOption>(()=>({xAxis:{name:'投资额'},yAxis:{name:'累计减排 tCO₂'},series:[{name:'场景',type:'scatter',symbolSize:14,data:comparisonItems.value.map(x=>[x.investment??null,x.cumulative_carbon_reduction_t??null])}]}))

async function initialize(){loading.value=true;error.value=null;try{await siteStore.loadSites();const requested=Number(route.query.scenario);await loadContext(requested||undefined)}catch(e){error.value=(e as {message?:string}).message||'场景管理加载失败'}finally{loading.value=false}}
async function loadContext(requested?:number){const site=siteStore.currentSite;if(!site){scenarios.value=[];return}scenarios.value=await scenariosApi.list(site.enterprise_id);await Promise.all(scenarios.value.map(async s=>versionMap[s.id]=await scenariosApi.versions(s.id)));[recommendationRuns.value,batches.value]=await Promise.all([recommendationsApi.list(site.enterprise_id),simulationApi.batches(site.enterprise_id)]);selectedScenarioId.value=scenarios.value.some(x=>x.id===requested)?requested||null:scenarios.value[0]?.id||null;if(currentScenario.value){selectedVersionId.value=currentScenario.value.current_version_id||versions.value.at(-1)?.id||null}selectedBatchId.value=batches.value[0]?.id||null;batch.value=batches.value[0]||null}
function selectScenario(id:number){selectedScenarioId.value=id;const scenario=scenarios.value.find(x=>x.id===id);selectedVersionId.value=scenario?.current_version_id||versionMap[id]?.at(-1)?.id||null;router.replace({query:{scenario:id}})}
function selectVersion(id:number){selectedVersionId.value=id}
function openNewVersion(){if(!currentScenario.value)return;const current=currentVersion(currentScenario.value);if(!current)return;selectedVersionId.value=current.id;snapshotText.value=JSON.stringify(current.parameter_snapshot_json,null,2);snapshotError.value=null;createVisible.value=true}
async function createVersion(){if(!currentScenario.value)return;snapshotError.value=null;try{const raw=JSON.parse(snapshotText.value) as Record<string,unknown>,payload:ScenarioVersionCreate={name:String(raw.name||currentScenario.value.name),description:raw.description==null?currentScenario.value.description:String(raw.description),base_year:Number(raw.base_year??currentScenario.value.base_year),start_year:Number(raw.start_year??currentScenario.value.start_year),end_year:Number(raw.end_year??currentScenario.value.end_year),target_peak_year:raw.target_peak_year==null?null:Number(raw.target_peak_year),target_neutral_year:raw.target_neutral_year==null?null:Number(raw.target_neutral_year),baseline_growth_json:typeof raw.baseline_growth_json==='object'&&raw.baseline_growth_json?raw.baseline_growth_json as Record<string,unknown>:{},status:String(raw.status||currentScenario.value.status),scenario_type:String(raw.scenario_type||currentScenario.value.scenario_type),measures:Array.isArray(raw.measures)?raw.measures as ScenarioVersionCreate['measures']:[]};const created=await scenariosApi.createVersion(currentScenario.value.id,payload);versionMap[currentScenario.value.id]=await scenariosApi.versions(currentScenario.value.id);scenarios.value=await scenariosApi.list(siteStore.currentSite!.enterprise_id);selectedVersionId.value=created.id;createVisible.value=false}catch(e){snapshotError.value=(e as {message?:string}).message||'快照 JSON 或版本参数无效'}}
function toggleBatchVersion(id:number){selectedVersionIds.value=selectedVersionIds.value.includes(id)?selectedVersionIds.value.filter(x=>x!==id):[...selectedVersionIds.value,id];if(!selectedVersionIds.value.includes(baselineVersionId.value||-1))baselineVersionId.value=null}
function prepareBatch(){selectedVersionIds.value=scenarios.value.map(x=>x.current_version_id).filter((x):x is number=>Boolean(x));const baseline=scenarios.value.find(x=>x.scenario_type==='BASELINE'&&x.current_version_id&&selectedVersionIds.value.includes(x.current_version_id));baselineVersionId.value=baseline?.current_version_id||null}
async function runBatch(){operationError.value=null;if(selectedVersionIds.value.length<2){operationError.value='请至少选择两个场景版本';return}if(!baselineVersionId.value){operationError.value='没有 BASELINE 类型时，必须明确选择一个基准版本';return}busy.value=true;try{batch.value=await simulationApi.runBatch({site_id:siteStore.currentSite!.id,enterprise_id:siteStore.currentSite!.enterprise_id,scenario_version_ids:selectedVersionIds.value,baseline_scenario_version_id:baselineVersionId.value,year:batchYear.value,electricity_price_per_kwh:buyPrice.value,feed_in_tariff_per_kwh:sellPrice.value,store_hourly_results:true});batches.value=[batch.value,...batches.value];selectedBatchId.value=batch.value.id}catch(e){operationError.value=(e as {message?:string}).message||'批量推演失败'}finally{busy.value=false}}
async function loadBatch(){if(!selectedBatchId.value)return;busy.value=true;try{batch.value=await simulationApi.getBatch(selectedBatchId.value)}catch(e){operationError.value=(e as {message?:string}).message||'批次加载失败'}finally{busy.value=false}}
onMounted(initialize)
</script>

<template><section><PageHeader kicker="SCENARIO PORTFOLIO" title="场景管理与多场景推演" description="以不可变 ScenarioVersion 为唯一仿真输入，批量运行并展示后端统一比较结果。"><el-button :loading="loading" @click="initialize"><el-icon><Refresh/></el-icon>刷新</el-button></PageHeader>
<LoadingState v-if="loading"/><ErrorState v-else-if="error" :message="error" @retry="initialize"/><template v-else-if="scenarios.length">
<div class="scenario-workspace"><aside class="scenario-list"><div class="list-title"><span>FORMAL SCENARIOS</span><b>{{scenarios.length}} 个场景</b></div><button v-for="s in scenarios" :key="s.id" :class="{active:selectedScenarioId===s.id}" @click="selectScenario(s.id)"><div><strong>{{s.name}}</strong><el-tag size="small">{{typeLabels[s.scenario_type]||s.scenario_type}}</el-tag></div><span>#{{s.id}} · 当前 V{{currentVersion(s)?.version_number||'—'}} · {{versionMap[s.id]?.length||0}} 个版本</span><small>{{currentVersion(s)?.source_recommendation_id?'推荐路径转换':'用户/系统创建'}} · 更新 {{new Date(latestTime(s)).toLocaleString('zh-CN')}}</small></button></aside>
<main v-if="currentScenario"><article class="panel"><div class="scenario-detail-head"><div><span>SCENARIO #{{currentScenario.id}}</span><h2>{{currentScenario.name}}</h2><p>{{currentScenario.description||'暂无描述'}}</p></div><div><el-tag size="large">{{typeLabels[currentScenario.scenario_type]||currentScenario.scenario_type}}</el-tag><StatusTag :status="currentScenario.status"/></div></div><div class="scenario-meta"><div><span>关联 Site / 企业</span><strong>{{siteStore.currentSite?.name}} / #{{currentScenario.enterprise_id}}</strong></div><div><span>当前版本</span><strong>V{{currentVersion(currentScenario)?.version_number}} · #{{currentScenario.current_version_id}}</strong></div><div><span>参数摘要</span><strong>{{measureSummary(currentVersion(currentScenario))}}</strong></div><div><span>来源推荐</span><template v-if="source(currentVersion(currentScenario))"><strong>#{{currentVersion(currentScenario)?.source_recommendation_id}} · {{source(currentVersion(currentScenario))?.path.profile}} · Rank {{source(currentVersion(currentScenario))?.path.rank}} · {{source(currentVersion(currentScenario))?.path.score.toFixed(4)}}</strong><el-button link @click="router.push({path:'/recommendations',query:{run:source(currentVersion(currentScenario))?.run.id}})">查看原推荐</el-button></template><strong v-else>非推荐来源 / 暂无追溯数据</strong></div></div><div class="scenario-actions"><el-button @click="selectedVersionId=currentScenario.current_version_id||null">查看当前版本</el-button><el-button type="primary" :disabled="Boolean(baselineContext?.locked)" @click="openNewVersion">{{baselineContext?.locked?'实验基准已锁定':'基于当前版本创建新版本'}}</el-button><el-button @click="router.push({path:'/simulation',query:{scenario_version:selectedVersionId}})">进入仿真推演</el-button></div></article>

<article v-if="baselineContext" class="panel baseline-evidence" data-testid="experiment-baseline"><div class="panel-head"><div><span>EXPERIMENT BASELINE</span><h2>实验基准 · 不可变版本 #{{selectedVersion?.id}}</h2></div><el-tag type="success">已锁定</el-tag></div><el-alert title="该基准只使用冻结的 BDG2 站点输入；后续实验必须与此版本比较，不能覆盖。" type="info" :closable="false"/><div class="snapshot-summary"><span>数据来源 {{baselineContext.dataset_provenance?.dataset_id}}</span><span>5 栋真实建筑</span><span>{{baselineContext.time_range?.start_utc}} — {{baselineContext.time_range?.end_utc_exclusive}}</span><span>完整率 {{((baselineContext.time_range?.completeness_rate??0)*100).toFixed(2)}}%</span></div><div class="scenario-meta"><div><span>基准总能耗</span><strong>{{baselineNumber('total_energy_kwh','kWh')}}</strong></div><div><span>基准排放</span><strong>{{baselineNumber('total_emission_tco2e','tCO₂e')}}</strong></div><div><span>基准峰值</span><strong>{{baselineNumber('peak_load_kw','kW')}}</strong></div><div><span>最大守恒误差</span><strong>{{baselineNumber('max_energy_balance_error_kwh','kWh')}}</strong></div><div><span>成本口径</span><strong>NOT_VERIFIED · 电价仅 FUNCTION_PARAMETER_ONLY</strong></div><div><span>模型版本</span><strong>{{baselineContext.model_versions?.hourly_simulation}}</strong></div><div><span>参数来源</span><strong>负荷/气象 REAL_PUBLIC · 因子 REAL_PUBLIC_OFFICIAL</strong></div><div><span>三套输入口径</span><strong>{{baselineContext.accounting_simulation_bridge?.status}} · 差值 {{baselineContext.accounting_simulation_bridge?.difference_kwh}} kWh</strong></div></div></article>

<div class="version-snapshot-layout"><article class="panel version-timeline"><div class="panel-head"><div><span>IMMUTABLE HISTORY</span><h2>版本时间线</h2></div><el-tag type="warning">历史版本不可修改</el-tag></div><el-timeline><el-timeline-item v-for="v in [...versions].reverse()" :key="v.id" :timestamp="new Date(v.created_at).toLocaleString('zh-CN')" :type="selectedVersionId===v.id?'primary':''"><button :class="{active:selectedVersionId===v.id}" @click="selectVersion(v.id)"><strong>V{{v.version_number}} · Version #{{v.id}}</strong><span>{{typeLabels[v.scenario_type]||v.scenario_type}} · {{measureSummary(v)}}</span><small v-if="v.source_recommendation_id">来源 Recommendation #{{v.source_recommendation_id}}</small></button></el-timeline-item></el-timeline></article>
<article v-if="selectedVersion" class="panel snapshot-panel"><div class="panel-head"><div><span>PARAMETER SNAPSHOT</span><h2>V{{selectedVersion.version_number}} 完整参数快照</h2></div><el-button @click="router.push({path:'/simulation',query:{scenario_version:selectedVersion.id}})">进入仿真</el-button></div><div class="snapshot-summary"><span>仿真年份 {{selectedVersion.parameter_snapshot_json.start_year??'暂无数据'}}—{{selectedVersion.parameter_snapshot_json.end_year??'暂无数据'}}</span><span>达峰/中和 {{selectedVersion.parameter_snapshot_json.target_peak_year??'无法判断'}} / {{selectedVersion.parameter_snapshot_json.target_neutral_year??'无法判断'}}</span><span>碳配额 {{selectedVersion.parameter_snapshot_json.carbon_quota_t??'暂无数据'}}</span><span>能耗目标 {{selectedVersion.parameter_snapshot_json.energy_target_kwh??'暂无数据'}}</span><span>预算 {{selectedVersion.parameter_snapshot_json.budget??'暂无数据'}}</span></div><h3>七类措施参数</h3><el-collapse><el-collapse-item v-for="m in selectedVersion.parameter_snapshot_json.measures||[]" :key="m.measure_type" :title="`${m.measure_type} · ${m.start_year}—${m.end_year||'持续'}`"><pre>{{JSON.stringify(m.parameters_json,null,2)}}</pre></el-collapse-item></el-collapse><h3>电价、因子、绿电及扩展快照</h3><pre>{{JSON.stringify({electricity_price_per_kwh:selectedVersion.parameter_snapshot_json.electricity_price_per_kwh,feed_in_tariff_per_kwh:selectedVersion.parameter_snapshot_json.feed_in_tariff_per_kwh,emission_factor:selectedVersion.parameter_snapshot_json.emission_factor,green_power:selectedVersion.parameter_snapshot_json.green_power,carbon_market:selectedVersion.carbon_market_snapshot_json||selectedVersion.parameter_snapshot_json.carbon_market,risk_parameters:selectedVersion.risk_parameter_snapshot_json||selectedVersion.parameter_snapshot_json.risk_parameters},null,2)}}</pre></article></div></main></div>

<article class="panel batch-panel"><div class="panel-head"><div><span>SIMULATION BATCH</span><h2>多场景批量推演</h2></div><el-button @click="prepareBatch">选择全部当前版本</el-button></div><div class="batch-config"><div class="version-picker"><button v-for="s in scenarios" :key="s.id" :class="{selected:selectedVersionIds.includes(s.current_version_id||-1)}" @click="s.current_version_id&&toggleBatchVersion(s.current_version_id)"><el-checkbox :model-value="selectedVersionIds.includes(s.current_version_id||-1)"/> <b>{{s.name}}</b><span>V{{currentVersion(s)?.version_number}} · #{{s.current_version_id}} · {{typeLabels[s.scenario_type]}}</span><el-radio :model-value="baselineVersionId" :value="s.current_version_id" @click.stop="baselineVersionId=s.current_version_id||null">Baseline</el-radio></button></div><div class="batch-fields"><label>仿真年份<el-input-number v-model="batchYear"/></label><label>固定购电价 fallback<el-input-number v-model="buyPrice" :step=".01"/></label><label>固定上网电价 fallback<el-input-number v-model="sellPrice" :step=".01"/></label><el-button type="primary" size="large" :loading="busy" @click="runBatch">提交批量推演</el-button></div></div><el-alert v-if="!baselineVersionId&&selectedVersionIds.length" title="未发现已选 BASELINE，请明确指定基准版本" type="warning" :closable="false"/><el-alert v-if="operationError" :title="operationError" type="error" :closable="false"/></article>

<article class="panel batch-result"><div class="panel-head"><div><span>BATCH STATUS</span><h2>批量任务状态</h2></div><el-select v-model="selectedBatchId" placeholder="历史批次" @change="loadBatch"><el-option v-for="b in batches" :key="b.id" :label="`Batch #${b.id} · ${b.status} · ${new Date(b.created_at).toLocaleString('zh-CN')}`" :value="b.id"/></el-select></div><template v-if="batch"><div class="batch-stats"><div><span>Batch ID</span><b>#{{batch.id}}</b></div><div><span>状态</span><StatusTag :status="batch.status"/></div><div><span>总场景</span><b>{{batch.items.length}}</b></div><div><span>成功</span><b>{{successful}}</b></div><div><span>失败</span><b>{{failed}}</b></div><div><span>Baseline</span><b>#{{batch.baseline_scenario_version_id}}</b></div></div><el-table :data="batch.items"><el-table-column label="场景版本"><template #default="{row}">{{scenarioName(row.scenario_version_id)}} · #{{row.scenario_version_id}}</template></el-table-column><el-table-column prop="task_id" label="Task ID"><template #default="{row}">{{row.task_id??'—'}}</template></el-table-column><el-table-column label="状态"><template #default="{row}"><StatusTag :status="row.status"/></template></el-table-column><el-table-column prop="error_message" label="失败原因"><template #default="{row}">{{row.error_message||'—'}}</template></el-table-column></el-table></template><EmptyState v-else title="暂无多场景推演结果" description="选择至少两个版本并指定基准后提交"/></article>

<template v-if="comparisonItems.length"><section class="scenario-cards"><article v-for="item in comparisonItems" :key="item.scenario_version_id" :class="{baseline:item.scenario_version_id===batch?.baseline_scenario_version_id,warning:(item.max_energy_balance_error_kwh??0)>1e-6}"><header><div><span>{{typeLabels[item.scenario_type||versionType(item.scenario_version_id)]}}</span><h3>{{scenarioName(item.scenario_version_id)}}</h3></div><el-tag v-if="item.scenario_version_id===batch?.baseline_scenario_version_id">Baseline</el-tag></header><dl><dt>总碳排</dt><dd>{{value(item.cumulative_carbon_emission_t)}} tCO₂</dd><dt>减排量 / 率</dt><dd>{{value(item.cumulative_carbon_reduction_t)}} / {{displayMetric('reduction_rate',item.reduction_rate)}}</dd><dt>总电费</dt><dd>{{value(item.total_electricity_cost)}}</dd><dt>投资 / 回收期</dt><dd>{{value(item.investment)}} / {{item.payback_years==null?'暂无数据':`${value(item.payback_years)} 年`}}</dd><dt>目标满足度</dt><dd>{{displayMetric('target_satisfaction',item.target_satisfaction)}}</dd><dt>最大守恒误差</dt><dd>{{value(item.max_energy_balance_error_kwh)}} kWh</dd></dl><el-alert v-if="(item.max_energy_balance_error_kwh??0)>1e-6" title="守恒误差异常，结果需要复核" type="error" :closable="false"/><div class="goal-grid"><span>达峰目标 <b>无法判断</b></span><span>中和目标 <b>无法判断</b></span><span>碳配额 <b>无法判断</b></span><span>综合能耗目标 <b>无法判断</b></span></div><div class="scenario-result-links"><el-button link @click="router.push({path:'/simulation',query:{scenario_version:item.scenario_version_id}})">进入单场景仿真</el-button><el-button v-if="item.task_id" link @click="router.push({path:'/carbon-market',query:{scenario_version:item.scenario_version_id,task:item.task_id,batch:batch?.id}})">查看碳市场分析</el-button><el-button v-if="item.task_id" link @click="router.push({path:'/risks',query:{scenario_version:item.scenario_version_id,task:item.task_id}})">查看风险评估</el-button></div></article></section>
<article class="panel comparison-table"><div class="panel-head"><div><span>13 METRICS</span><h2>后端统一场景比较</h2></div><span class="panel-note">差值和变化率均直接读取 comparison_json</span></div><el-table :data="comparisonItems" border><el-table-column fixed label="场景" width="180"><template #default="{row}">{{scenarioName(row.scenario_version_id)}}</template></el-table-column><el-table-column v-for="key in batchMetrics" :key="key" :label="metricLabels[key]||key" min-width="140"><template #default="{row}">{{displayMetric(key,row[key])}}</template></el-table-column></el-table></article>
<section class="scenario-chart-grid"><article class="panel"><h3>累计碳排</h3><BaseChart :option="carbonOption"/></article><article class="panel"><h3>累计减排</h3><BaseChart :option="reductionOption"/></article><article class="panel"><h3>总购电量</h3><BaseChart :option="gridOption"/></article><article class="panel"><h3>可再生能源发电</h3><BaseChart :option="renewableOption"/></article><article class="panel"><h3>可再生能源自用率</h3><BaseChart :option="selfUseOption"/></article><article class="panel"><h3>总电费</h3><BaseChart :option="costOption"/></article><article class="panel"><h3>投资额与回收期</h3><BaseChart :option="investmentPaybackOption"/></article><article class="panel"><div class="chart-title"><h3>基准差值 / 变化率</h3><el-select v-model="comparisonMetric"><el-option v-for="key in batchMetrics" :key="key" :label="metricLabels[key]||key" :value="key"/></el-select></div><BaseChart :option="deltaOption"/></article><article class="panel wide"><h3>减排量—投资额</h3><BaseChart :option="scatterOption"/></article></section></template><EmptyState v-else title="暂无多场景推演结果" description="批次完成后显示统一比较"/>
</template><EmptyState v-else title="暂无场景，可先从低碳路径推荐生成场景" description="前往低碳路径推荐并将推荐路径转换为正式场景"><el-button type="primary" @click="router.push('/recommendations')">前往推荐</el-button></EmptyState>
<el-dialog v-model="createVisible" title="基于当前版本创建新版本" width="780px"><el-alert title="提交将创建新的不可变版本，历史版本不会被覆盖" type="warning" :closable="false"/><el-input v-model="snapshotText" type="textarea" :rows="22" class="snapshot-editor"/><el-alert v-if="snapshotError" :title="snapshotError" type="error" :closable="false"/><template #footer><el-button @click="createVisible=false">取消</el-button><el-button type="primary" :loading="busy" @click="createVersion">创建新版本</el-button></template></el-dialog>
</section></template>
